import numpy as np

class CrossSiloFL:
    def __init__(self, num_silos, min_silos_ratio=0.8):
        self.num_silos = num_silos
        self.min_silos = max(1, int(num_silos * min_silos_ratio))
        self.silo_reputation = np.ones(num_silos)
        self.silo_history = [[] for _ in range(num_silos)]
    def select_silos(self, round_num):
        probs = self.silo_reputation / np.sum(self.silo_reputation)
        selected = np.random.choice(self.num_silos, size=self.min_silos, replace=False, p=probs)
        return selected
    def check_stragglers(self, responses, timeout_rounds):
        return [i for i, r in enumerate(responses) if r is not None]
    def update_reputation(self, silo_id, loss_improvement):
        alpha = 0.1
        self.silo_reputation[silo_id] = (1 - alpha) * self.silo_reputation[silo_id] + alpha * max(0, loss_improvement)
        self.silo_reputation[silo_id] = np.clip(self.silo_reputation[silo_id], 0.1, 2.0)
    def reputation_weighted_aggregate(self, silo_weights, silo_ids, sample_sizes):
        eff = np.array([sample_sizes[i] * self.silo_reputation[silo_ids[i]] for i in range(len(silo_ids))])
        total = np.sum(eff)
        return {k: sum(e * w[k] for e, w in zip(eff, silo_weights)) / total for k in silo_weights[0]}
